from collections import deque

class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        result = []
        dq = deque()  # 存储索引

        for i in range(len(nums)):
            # 移除超出窗口的元素
            while dq and dq[0] < i - k + 1:
                dq.popleft()

            # 移除队列尾部比当前元素小的
            while dq and nums[dq[-1]] < nums[i]:
                dq.pop()

            dq.append(i)

            # 窗口形成后记录最大值
            if i >= k - 1:
                result.append(nums[dq[0]])

        return result
